const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function journeySettings({campaign='odyssey',mode='explore',seed='',open=false}={}){
 return`<details class="journey-settings" id="journey-settings" ${open?'open':''}><summary>旅程设置 <span>可选</span></summary><div class="journey-settings-body"><fieldset><legend>死亡规则</legend><div class="difficulty-choices">${[['explore','营火重生 · 推荐','保留生存挑战；倒下后可在原岛营火重生，找回遗落材料。'],['survival','死亡后重新开始','适合熟悉荒野后挑战，死亡后本次旅程结束。']].map(([id,title,text])=>`<button data-difficulty="${id}" class="${mode===id?'selected':''}" aria-pressed="${mode===id}"><b>${mode===id?'✓ ':''}${title}</b><small>${text}</small></button>`).join('')}</div></fieldset><label class="seed-setting">地图种子<input id="world-seed" inputmode="numeric" maxlength="10" value="${escape(seed)}" aria-label="地图种子"><small>默认随机。与朋友使用相同种子，可探索相同的资源分布。</small></label><fieldset><legend>成长规则</legend><div class="journey-choices">${[['odyssey','完整旅程 · 推荐','六地成长、营地伙伴与机械助手'],['classic','旧版成长规则','供熟悉旧版本的玩家选择']].map(([id,title,text])=>`<button data-campaign="${id}" class="${campaign===id?'selected':''}" aria-pressed="${campaign===id}"><b>${campaign===id?'✓ ':''}${title}</b><small>${text}</small></button>`).join('')}</div></fieldset></div></details>`;
}
